use std::time::SystemTime;

// Using SystemTime to measure elapsed duration for timeouts
fn run_with_timeout() {
    let start = SystemTime::now();
    loop {
        do_work();
        // BUG: SystemTime is non-monotonic! If NTP shifts clock backward,
        // this can loop forever, or exit prematurely if clock jumps forward.
        if start.elapsed().unwrap_or_default() > std::time::Duration::from_secs(10) {
            break;
        }
    }
}
